// static
bool StructTraits<::brave_rewards::mojom::RewardsEngineOptions::DataView, ::brave_rewards::mojom::RewardsEngineOptionsPtr>::Read(
    ::brave_rewards::mojom::RewardsEngineOptions::DataView input,
    ::brave_rewards::mojom::RewardsEngineOptionsPtr* output) {
  bool success = true;
  ::brave_rewards::mojom::RewardsEngineOptionsPtr result(::brave_rewards::mojom::RewardsEngineOptions::New());
  
      if (success && !input.ReadEnvironment(&result->environment))
        success = false;
      if (success)
        result->is_testing = input.is_testing();
      if (success)
        result->reconcile_interval = input.reconcile_interval();
      if (success)
        result->retry_interval = input.retry_interval();
      if (success)
        result->check_linkage_interval = input.check_linkage_interval();
      if (success && !input.ReadGate3Url(&result->gate3_url))
        success = false;
  *output = std::move(result);
  return success;
}

