void RewardsEngineAsyncWaiter::Initialize(
    ::brave_rewards::mojom::Result* out_result) {
  base::RunLoop loop;
  proxy_->Initialize(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::brave_rewards::mojom::Result* out_result
,
             ::brave_rewards::mojom::Result result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

::brave_rewards::mojom::Result RewardsEngineAsyncWaiter::Initialize(
    ) {
  ::brave_rewards::mojom::Result async_wait_result;
  Initialize(&async_wait_result);
  return async_wait_result;
}

